                    p.getRetirements().stream().map(r -> new HoldState(r.from(), r.to())).toList(), p.getTags(),
                    p.getDatedTerms().stream().map(t -> new TermsState(t.from(), t.terms())).toList()));
        } else if (entity instanceof Rate r) {
