  /** Transfer a person to another sheet; the row then leaves the list, and the sheet's people and
   *  claims are read again to show what they left behind. */
  protected async transfer(p: Person, toSheetId: string): Promise<void> {
    this.clearRowError(p.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    if (!toSheetId.trim()) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: 'Enter the id of the sheet to transfer to.' }));
      return;
    }
    try {
      await this.api.transfer(sheetId, p.id, toSheetId.trim());
      if (this.session.sheetId() !== sheetId) return;
      this.people.update((ps) => ps.filter((o) => o.id !== p.id));
      await this.read(sheetId);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: transferError(e) }));
    }
  }

  /** The last statement's due-total: blank with none, n/a when it was n/a. */
  protected statedTotalOf(p: Person): string {
    return p.statementCount === 0 ? '' : (p.statedTotal ?? 'n/a');
  }

  /** Take a statement of a person, as of the date entered (blank: now), which is then cleared; the
  ownFigures(sheetId: string): Promise<DescendantFigures> {
    return firstValueFrom(this.http.get<DescendantFigures>(
      `/api/sheets/${encodeURIComponent(sheetId)}/figures`, { headers: this.headers() }));
  }

  /** Transfer the person to another sheet; resolves to the person as they arrived there. */
  transfer(sheetId: string, id: number, toSheetId: string): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheetId)}/${id}/transfer`, { toSheetId }, { headers: this.headers() }),
    );
  }

  /** The figures of the sheet's descendants (its children, theirs, and so on), each as it is now
}

export function transferError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter the id of the sheet to transfer to.';
  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward may transfer people, and neither sheet may be archived.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on this sheet.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'Their name or an alias is used by more than one person there or elsewhere in its tree, or their contact is already on that sheet.';
  if (e instanceof HttpErrorResponse && e.status === 422) return 'A person is transferred only to another sheet, not once retired, and not into a retired person there.';
  return otherError(e);
}

export function patronError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Choose a patron.';

